{"Channel": {"name": "develop-hannahsmith-CollaborateForce", "channelID": "ch-force-ce946d"}, "Message": {"User": {"userId": "eid_76d9cb07", "timestamp": "2026-10-18T11:17:00", "text": "Hi team, I wanted to discuss our new PR on comprehensive API documentation. I've found some similar features in open-source projects that might give us some insights. Let's dive in! 😊", "utterranceID": "20261018-0-fcd7a"}, "Reactions": []}, "ThreadReplies": [], "id": "20261018-0-fcd7a"}
