{"Channel": {"name": "bug-juliataylor-SearchForce", "channelID": "ch-force-1897c0"}, "Message": {"User": {"userId": "eid_d0b6cb92", "timestamp": "2027-02-15T09:48:00", "text": "Thanks, David Jones! This should really improve the user experience on mobile. Let me know if you need any help with further testing.", "utterranceID": "20270214-4-79a31"}, "Reactions": []}, "ThreadReplies": [], "id": "20270214-4-79a31"}
