{"Channel": {"name": "planning-SlackSummarizer", "channelID": "ch-rizer-d7d419"}, "Message": {"User": {"userId": "eid_e96d2f38", "timestamp": "2026-09-27T03:20:00", "text": "Hey @eid_03a183c9, sounds good! I think we should start with the problem statement and objectives. We need to clearly define what SlackSummarizer aims to solve. Thoughts?", "utterranceID": "20260926-1-c096f"}, "Reactions": []}, "ThreadReplies": [], "id": "20260926-1-c096f"}
