{"Channel": {"name": "bug-iansmith-TrendForce", "channelID": "ch-force-c56b63"}, "Message": {"User": {"userId": "eid_5782059f", "timestamp": "2026-08-21T17:40:00", "text": "Hi team, I looked into the reported issue about the 'Incorrect Seasonal Adjustment' in TrendForce.", "utterranceID": "20260821-0-7de39"}, "Reactions": []}, "ThreadReplies": [], "id": "20260821-0-7de39"}
