{"Channel": {"name": "bug-iansmith-TrendForce", "channelID": "ch-force-c56b63"}, "Message": {"User": {"userId": "eid_92c62291", "timestamp": "2026-08-21T17:50:00", "text": "Thanks for the update, George. So, it's not an issue with the production environment?", "utterranceID": "20260821-4-48efb"}, "Reactions": []}, "ThreadReplies": [], "id": "20260821-4-48efb"}
