{"Channel": {"name": "bug-iansmith-TrendForce", "channelID": "ch-force-c56b63"}, "Message": {"User": {"userId": "eid_01942cf0", "timestamp": "2026-09-26T00:05:00", "text": "Hi team, the bug about incorrect JWT signature verification has been resolved. You can check the details in the approved PR here: https://github.com/salesforce/TrendForce/pull/37.", "utterranceID": "20260925-0-eabad"}, "Reactions": []}, "ThreadReplies": [], "id": "20260925-0-eabad"}
{"Channel": {"name": "bug-iansmith-TrendForce", "channelID": "ch-force-c56b63"}, "Message": {"User": {"userId": "eid_01942cf0", "timestamp": "2026-09-26T00:07:00", "text": "The issue was due to an outdated cryptographic library that didn't support the latest JWT signing algorithms, which led to verification errors for some external applications.", "utterranceID": "20260925-1-213d1"}, "Reactions": []}, "ThreadReplies": [], "id": "20260925-1-213d1"}
