{"Channel": {"name": "develop-davidtaylor-VizForce", "channelID": "ch-force-4e46da"}, "Message": {"User": {"userId": "eid_bef4290f", "timestamp": "2026-08-13T17:15:00", "text": "Hi team, I wanted to discuss some open-source features that might give us insights for our new indexing strategy. Let's dive in! 😊", "utterranceID": "20260813-0-f42dc"}, "Reactions": []}, "ThreadReplies": [], "id": "20260813-0-f42dc"}
