{"Channel": {"name": "bug-emmagarcia-ContentForce", "channelID": "ch-force-f17ba0"}, "Message": {"User": {"userId": "eid_8436fc1f", "timestamp": "2026-07-12T14:44:00", "text": "Thanks, Emma! I'll dive into the Rasa PR and see if their approach can help us resolve our context issues. 🚀", "utterranceID": "20260712-6-4df2e"}, "Reactions": []}, "ThreadReplies": [], "id": "20260712-6-4df2e"}
