{"Channel": {"name": "develop-ianjones-ContentForce", "channelID": "ch-force-75e6bf"}, "Message": {"User": {"userId": "eid_88e74382", "timestamp": "2026-06-19T13:48:00", "text": "Thanks everyone for the quick response. Looking forward to the updates, @eid_3f4b2681.", "utterranceID": "20260619-11-fce7f"}, "Reactions": []}, "ThreadReplies": [], "id": "20260619-11-fce7f"}
