{"Channel": {"name": "bug-emmamartinez-ContentForce", "channelID": "ch-force-a1e3f0"}, "Message": {"User": {"userId": "eid_4350bf70", "timestamp": "2026-08-04T00:31:00", "text": "Hi team, several customers are reporting issues with ContentForce that we need to address ASAP. Let's go through them one by one. 🚀", "utterranceID": "20260803-0-4f526"}, "Reactions": []}, "ThreadReplies": [], "id": "20260803-0-4f526"}
