{"Channel": {"name": "bug-bobmiller-MonitorForce", "channelID": "ch-force-c6eeee"}, "Message": {"User": {"userId": "eid_44c67741", "timestamp": "2026-05-20T21:20:00", "text": "Hi team, several customers are reporting issues with MonitorForce that need our attention. Let's go through them one by one. 😊", "utterranceID": "20260520-0-3f0a2"}, "Reactions": []}, "ThreadReplies": [], "id": "20260520-0-3f0a2"}
