{"Channel": {"name": "develop-emmamartinez-ProposalForce", "channelID": "ch-force-888914"}, "Message": {"User": {"userId": "eid_8a2cd06b", "timestamp": "2027-03-25T17:29:00", "text": "Hi team, please check my PR for the authentication service refactor: https://github.com/salesforce/ProposalForce/pull/16. 🚀 This update moves our service to AWS Lambda for better scalability and performance. Let me know your thoughts!", "utterranceID": "20270326-0-2183e"}, "Reactions": []}, "ThreadReplies": [], "id": "20270326-0-2183e"}
