{"Channel": {"name": "bug-davidjohnson-SupportForce", "channelID": "ch-force-2e101e"}, "Message": {"User": {"userId": "eid_3f6f7744", "timestamp": "2026-09-23T22:03:00", "text": "If anyone wants to brainstorm or needs a second pair of eyes, just let me know. 🤝", "utterranceID": "20260923-7-7896a"}, "Reactions": []}, "ThreadReplies": [], "id": "20260923-7-7896a"}
