{"Channel": {"name": "develop-juliagarcia-ProposalForce", "channelID": "ch-force-d166d6"}, "Message": {"User": {"userId": "eid_379522c3", "timestamp": "2027-03-11T04:03:00", "text": "Hey @eid_8bab7c9d, I'll take a look too. Real-time collaboration is going to be a game-changer for us! 🔍", "utterranceID": "20270313-2-a2209"}, "Reactions": []}, "ThreadReplies": [], "id": "20270313-2-a2209"}
