{"Channel": {"name": "bug-hannahmiller-ConnectForce", "channelID": "ch-force-bd582c"}, "Message": {"User": {"userId": "eid_80cffa39", "timestamp": "2026-08-09T21:01:00", "text": "Sure thing! I'll dive into the Token Expiry Mismanagement issue and work on a fix. Thanks for assigning it to me! 🔧", "utterranceID": "20260809-6-d8b45"}, "Reactions": []}, "ThreadReplies": [], "id": "20260809-6-d8b45"}

